package cn.nemo.qingxiao;
import android.content.*;import org.json.*;import java.util.*;
public class SyncEngine {
 static final String[] ARRAYS={"items","sessions","catalogs","preferences"},KINDS={"item","session","catalog","preference"};
 static JSONObject find(JSONArray a,String id)throws Exception {if(a!=null)for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).optString("id")))return a.getJSONObject(i);return null;}
 static void replace(JSONArray a,JSONObject r)throws Exception{for(int i=0;i<a.length();i++)if(r.getString("id").equals(a.getJSONObject(i).getString("id"))){a.put(i,r);return;}a.put(r);}
 public static void run(Context c){if(MainActivity.foreground)return;try{for(int batch=0;batch<20;batch++){JSONArray changes=new JSONArray();synchronized(Store.class){JSONObject db=new JSONObject(Store.read(c));if(db.optInt("version")<3)return;for(int k=0;k<ARRAYS.length;k++){JSONArray a=db.optJSONArray(ARRAYS[k]);if(a==null)continue;for(int i=0;i<a.length()&&changes.length()<100;i++){JSONObject r=a.getJSONObject(i);if(!r.optBoolean("_dirty"))continue;JSONObject data=new JSONObject(r.toString());data.remove("_dirty");data.remove("_op");data.remove("_rev");changes.put(new JSONObject().put("id",r.getString("id")).put("kind",KINDS[k]).put("opId",r.getString("_op")).put("baseRev",r.optInt("_rev")).put("data",data));}}}
  JSONObject response=new JSONObject(CloudSync.sync(c,new JSONObject().put("schemaVersion",3).put("changes",changes).toString()));if(MainActivity.foreground)return;
  synchronized(Store.class){JSONObject db=new JSONObject(Store.read(c));JSONArray records=response.getJSONArray("records"),acks=response.getJSONArray("acknowledgements");for(int k=0;k<ARRAYS.length;k++)if(!db.has(ARRAYS[k]))db.put(ARRAYS[k],new JSONArray());
   for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);int k=Arrays.asList(KINDS).indexOf(r.getString("kind"));if(k<0)continue;JSONArray a=db.getJSONArray(ARRAYS[k]);String id=r.getString("id");JSONObject local=find(a,id),ack=find(acks,id);int rev=r.getInt("rev");if(local!=null&&local.optInt("_rev")>rev)continue;JSONObject remote=r.getJSONObject("data").put("_rev",rev).put("_dirty",false);
    if(local!=null&&local.optBoolean("_dirty")){if(ack!=null&&ack.optString("opId").equals(local.optString("_op"))){if(ack.optInt("accepted")==0){JSONObject copy=new JSONObject(local.toString());copy.put("id",UUID.randomUUID().toString()).put("_rev",0).put("_dirty",true).put("_op",UUID.randomUUID().toString()).put("conflictOf",id).put("conflictAt",System.currentTimeMillis());if(copy.has("title"))copy.put("title",copy.optString("title")+"（冲突副本）");if(copy.has("name"))copy.put("name",copy.optString("name")+"（冲突副本）");a.put(copy);}replace(a,remote);}else if(ack!=null&&ack.optInt("accepted")==1)local.put("_rev",Math.max(local.optInt("_rev"),ack.optInt("rev")));}else replace(a,remote);
   }
   for(int i=0;i<acks.length();i++){JSONObject ack=acks.getJSONObject(i);if(find(records,ack.getString("id"))!=null)continue;for(String name:ARRAYS){JSONObject r=find(db.getJSONArray(name),ack.getString("id"));if(r!=null&&r.optBoolean("_dirty")&&r.optString("_op").equals(ack.optString("opId"))){if(ack.optInt("accepted")==1)r.put("_dirty",false).put("_rev",ack.optInt("rev"));else if(ack.optInt("rev")==0)r.put("_rev",0).put("_op",UUID.randomUUID().toString());}}}
   db.put("version",3);Store.write(c,db.toString());
  }if(changes.length()<100){Photos.sync(c,Photos.ids(c));break;}
 }}catch(Exception e){/* Dirty records remain in local storage for the next attempt. */}}
}
